import unittest

from text import slugify


class TestSlugify(unittest.TestCase):
    def test_basic_phrase(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_punctuation_removed(self):
        self.assertEqual(slugify("Hello, World!"), "hello-world")

    def test_separator_runs_collapse(self):
        self.assertEqual(slugify("a  b -- c__d"), "a-b-c-d")

    def test_leading_trailing_separators_stripped(self):
        self.assertEqual(slugify("  --Hello--  "), "hello")

    def test_accents_transliterated(self):
        self.assertEqual(slugify("Crème Brûlée"), "creme-brulee")

    def test_numbers_preserved(self):
        self.assertEqual(slugify("Chapter 12: The End"), "chapter-12-the-end")

    def test_already_slug_unchanged(self):
        self.assertEqual(slugify("already-a-slug"), "already-a-slug")

    def test_empty_string(self):
        self.assertEqual(slugify(""), "")

    def test_only_punctuation(self):
        self.assertEqual(slugify("!!!"), "")


if __name__ == "__main__":
    unittest.main()

